def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent
    """
    if not classes:
        return []

    # Create a dictionary to store the base classes and their dependencies
    base_dict = {cls: set(cls.__bases__) for cls in classes}

    # Find the minimal set of base classes
    minimal = set()
    for cls in classes:
        if not any(base in minimal for base in base_dict[cls]):
            minimal.add(cls)

    # Sort the minimal set of base classes
    minimal = sorted(minimal, key=lambda x: classes.index(x))

    return minimal

