def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")
    if not all(isinstance(char, str) and len(char) == 1 for char in alphabet):
        raise ValueError("Alphabet must contain single characters")
    if number < 0:
        raise ValueError("Number must be non-negative")
    if padding is not None and padding < 0:
        raise ValueError("Padding must be non-negative")

    base = len(alphabet)
    if number == 0:
        return alphabet[0] * (padding if padding is not None else 1)

    result = []
    while number > 0:
        result.append(alphabet[number % base])
        number //= base

    if padding is not None:
        result.extend([alphabet[0]] * (padding - len(result)))

    return ''.join(reversed(result))

